7. import org.cqfn.diktat.ruleset.rules.DiktatRule
8. import org.cqfn.diktat.ruleset.utils.*
9. 
10. import com.pinterest.ktlint.core.ast.ElementType
11. import com.pinterest.ktlint.core.ast.ElementType.CALL_EXPRESSION
12. import com.pinterest.ktlint.core.ast.ElementType.FUNCTION_LITERAL
13. import com.pinterest.ktlint.core.ast.ElementType.IDENTIFIER
14. import com.pinterest.ktlint.core.ast.ElementType.LAMBDA_EXPRESSION
15. import com.pinterest.ktlint.core.ast.ElementType.RBRACE
16. import com.pinterest.ktlint.core.ast.ElementType.VALUE_ARGUMENT_LIST
17. import com.pinterest.ktlint.core.ast.ElementType.VALUE_PARAMETER
18. import com.pinterest.ktlint.core.ast.ElementType.WHITE_SPACE
19. import org.jetbrains.kotlin.com.intellij.lang.ASTNode
20. import org.jetbrains.kotlin.com.intellij.psi.impl.source.tree.LeafPsiElement
21. import org.jetbrains.kotlin.com.intellij.psi.impl.source.tree.PsiWhiteSpaceImpl
22. import org.jetbrains.kotlin.psi.psiUtil.parents
23. 
24. /**
25.  * Rule that checks if empty code blocks (`{  }`) are used and checks their formatting.
26.  */
27. class EmptyBlock(configRules: List<RulesConfig>) : DiktatRule(
28.     NAME_ID,
29.     configRules,
30.     listOf(EMPTY_BLOCK_STRUCTURE_ERROR)
31. ) {
32.     override fun logic(node: ASTNode) {
33.         val configuration = EmptyBlockStyleConfiguration(
34.             configRules.getRuleConfig(EMPTY_BLOCK_STRUCTURE_ERROR)?.configuration ?: emptyMap()
35.         )
36.         searchNode(node, configuration)
37.     }
38. 
39.     private fun searchNode(node: ASTNode, configuration: EmptyBlockStyleConfiguration) {
40.         val newNode = node.findLBrace()?.treeParent ?: return
41.         checkEmptyBlock(newNode, configuration)
42.     }
43. 
44.     private fun isNewLine(node: ASTNode) =
45.         node.findChildByType(WHITE_SPACE)?.text?.contains("\n") ?: false
46. 
47.     @Suppress("UnsafeCallOnNullableType", "TOO_LONG_FUNCTION")
48.     private fun checkEmptyBlock(node: ASTNode, configuration: EmptyBlockStyleConfiguration) {
49.         if (node.treeParent.isOverridden() || isAnonymousSamClass(node) || isLambdaUsedAsFunction(node)) {
50.             return
51.         }
52.         if (node.isBlockEmpty()) {
53.             if (!configuration.emptyBlockExist) {
54.                 EMPTY_BLOCK_STRUCTURE_ERROR.warn(configRules, emitWarn, isFixMode, "empty blocks are forbidden unless it is function with override keyword",
55.                     node.startOffset, node)
56.             } else {
57.                 node.findParentNodeWithSpecificType(ElementType.LAMBDA_ARGUMENT)?.let {
58.                     // Lambda body is always has a BLOCK -> run { } - (LBRACE, WHITE_SPACE, BLOCK "", RBRACE)
59.                     if (isNewLine(node)) {
60.                         val freeText = "do not put newlines in empty lambda"
61.                         EMPTY_BLOCK_STRUCTURE_ERROR.warnAndFix(configRules, emitWarn, isFixMode, freeText, node.startOffset, node) {
62.                             val whiteSpaceNode = node.findChildByType(WHITE_SPACE)
63.                             whiteSpaceNode?.let {
64.                                 node.replaceChild(whiteSpaceNode, PsiWhiteSpaceImpl(" "))
65.                             }
66.                         }
67.                     }
68.                     return
69.                 }
70.                 val space = node.findChildByType(RBRACE)!!.treePrev
71.                 if (configuration.emptyBlockNewline && !space.text.contains("\n")) {
72.                     EMPTY_BLOCK_STRUCTURE_ERROR.warnAndFix(configRules, emitWarn, isFixMode, "different style for empty block",
73.                         node.startOffset, node) {
74.                         if (space.elementType == WHITE_SPACE) {
75.                             (space.treeNext as LeafPsiElement).rawReplaceWithText("\n")
76.                         } else {
77.                             node.addChild(PsiWhiteSpaceImpl("\n"), space.treeNext)
78.                         }
79.                     }
80.                 } else if (!configuration.emptyBlockNewline && space.text.contains("\n")) {
81.                     EMPTY_BLOCK_STRUCTURE_ERROR.warnAndFix(configRules, emitWarn, isFixMode, "different style for empty block",
82.                         node.startOffset, node) {
83.                         node.removeChild(space)
84.                     }
85.                 }
86.             }
87.         }
88.     }
89. 
90.     @Suppress("UnsafeCallOnNullableType")
91.     private fun isAnonymousSamClass(node: ASTNode): Boolean =
92.         if (node.elementType == FUNCTION_LITERAL && node.hasParent(CALL_EXPRESSION)) {
93.             // We are checking identifier because it is not class in AST,
94.             // SAM conversions are indistinguishable from lambdas.
95.             // So we just verify that identifier is in PascalCase
96.             val valueArgument = node.findParentNodeWithSpecificType(CALL_EXPRESSION)!!
97.             valueArgument.findLeafWithSpecificType(IDENTIFIER)?.text?.isPascalCase() ?: false
98.         } else {
99.             false
100.         }
101. 
102.     @Suppress("UnsafeCallOnNullableType")
103.     private fun isLambdaUsedAsFunction(node: ASTNode): Boolean {
104.         val parents = node.parents()
105.         return when {
106.             parents.any { it.elementType == CALL_EXPRESSION } -> {
107.                 val callExpression = parents.find { it.elementType == CALL_EXPRESSION }!!
108.                 // excepting cases like list.map { }. In this case call expression will not have value argument list
109.                 // And in this case: Parser.parse({}, some, thing) it will have value argument list
110.                 callExpression.hasChildOfType(VALUE_ARGUMENT_LIST)
111.             }
112.             parents.any { it.elementType == LAMBDA_EXPRESSION } -> {
113.                 val lambdaExpression = parents.find { it.elementType == LAMBDA_EXPRESSION }!!
114.                 // cases like A({}). Here Lambda expression is used as a value parameter.
115.                 lambdaExpression.treeParent.elementType == VALUE_PARAMETER
116.             }
117.             else -> false
118.         }
119.     }
120. 
121.     /**
122.      * [RuleConfiguration] for empty blocks formatting
123.      */
124.     class EmptyBlockStyleConfiguration(config: Map<String, String>) : RuleConfiguration(config) {
125.         /**
126.          * Whether empty code blocks should be allowed
127.          */
128.         val emptyBlockExist = config["allowEmptyBlocks"]?.toBoolean() ?: false
129. 
130.         /**
131.          * Whether a newline after `{` is required in an empty block
132.          */
133.         val emptyBlockNewline = config["styleEmptyBlockWithNewline"]?.toBoolean() ?: true
134.     }
135. 
136.     companion object {
137.         const val NAME_ID = "empty-block-structure"
138.     }
139. }
